=== FILE: tick_timer_cov_tb.sv ===
// Coverage-closing testbench for tick_timer.v (W = 16). Extends the approved
// idle testbench: one-shot and periodic counting, expiry, W1C clear, expiry
// winning over a clear, a CTRL write suppressing an expiry, stop, all-ones and
// all-zeros register traffic, and a reset in mid-run. Checks are cycle-exact.
`timescale 1ns / 1ps
module tick_timer_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    localparam logic [1:0] CTRL = 2'd0, LOAD = 2'd1, COUNT = 2'd2, STATUS = 2'd3;

    tick_timer #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .irq(irq));
    always #5 clk = ~clk;

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("MISMATCH t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata, expected);
        end
    endtask

    task automatic expect_irq(input logic expected);
        checks++;
        if (irq !== expected) begin
            errors++;
            $display("MISMATCH t=%0t irq=%b expected=%b", $time, irq, expected);
        end
    endtask

    task automatic write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1; addr = a; wdata = d;
        @(posedge clk); #1;
        we = 1'b0; wdata = 32'd0;
    endtask

    initial begin
        // Reset and reset values.
        repeat (3) @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);
        #1;
        expect_reg(CTRL, 32'd0);
        expect_reg(LOAD, 32'd0);
        expect_reg(COUNT, 32'd0);
        expect_reg(STATUS, 32'd0);
        expect_irq(1'b0);

        // One-shot with interrupt enabled: LOAD = 3, CTRL = EN | IE.
        write(LOAD, 32'd3);
        expect_reg(LOAD, 32'd3);
        write(CTRL, 32'h0000_0005);
        expect_reg(COUNT, 32'd3);
        @(posedge clk); #1;
        expect_reg(COUNT, 32'd2);
        repeat (3) @(posedge clk);
        #1;
        expect_reg(STATUS, 32'd1);
        expect_irq(1'b1);
        expect_reg(CTRL, 32'h0000_0004);
        expect_reg(COUNT, 32'd0);

        // W1C: writing 0 keeps the flag, writing 1 clears it.
        write(STATUS, 32'd0);
        expect_reg(STATUS, 32'd1);
        write(STATUS, 32'd1);
        expect_reg(STATUS, 32'd0);
        expect_irq(1'b0);

        // Periodic, interrupt disabled: LOAD = 2, CTRL = EN | MODE.
        write(LOAD, 32'd2);
        write(CTRL, 32'h0000_0003);
        expect_reg(COUNT, 32'd2);
        repeat (3) @(posedge clk);
        #1;
        expect_reg(STATUS, 32'd1);
        expect_reg(COUNT, 32'd2);
        expect_reg(CTRL, 32'h0000_0003);
        expect_irq(1'b0);
        @(posedge clk);
        @(posedge clk); #1;
        expect_reg(COUNT, 32'd0);
        // A clear at the same edge as an expiry loses to the expiry.
        write(STATUS, 32'd1);
        expect_reg(STATUS, 32'd1);
        expect_reg(COUNT, 32'd2);
        // Clear while counting (count 2 -> 1), then let it reach zero.
        write(STATUS, 32'd1);
        expect_reg(STATUS, 32'd0);
        expect_reg(COUNT, 32'd1);
        @(posedge clk); #1;
        // A CTRL write at the edge where the count is zero takes the expiry's place.
        write(CTRL, 32'h0000_0003);
        expect_reg(STATUS, 32'd0);
        expect_reg(COUNT, 32'd0);
        @(posedge clk); #1;
        expect_reg(STATUS, 32'd1);
        expect_reg(COUNT, 32'd2);
        // Stop: the CTRL write takes priority over the decrement.
        write(CTRL, 32'h0000_0002);
        expect_reg(CTRL, 32'h0000_0002);
        expect_reg(COUNT, 32'd2);
        @(posedge clk); #1;
        expect_reg(COUNT, 32'd2);
        write(STATUS, 32'd1);
        expect_reg(STATUS, 32'd0);

        // All-ones and all-zeros on the stored bits.
        write(LOAD, 32'hFFFF_FFFF);
        expect_reg(LOAD, 32'h0000_FFFF);
        write(CTRL, 32'h0000_0001);
        expect_reg(COUNT, 32'h0000_FFFF);
        @(posedge clk); #1;
        expect_reg(COUNT, 32'h0000_FFFE);
        write(CTRL, 32'h0000_0000);
        expect_reg(CTRL, 32'd0);
        expect_reg(COUNT, 32'h0000_FFFE);
        write(LOAD, 32'd0);
        expect_reg(LOAD, 32'd0);
        write(CTRL, 32'h0000_0001);
        expect_reg(COUNT, 32'd0);
        expect_reg(CTRL, 32'h0000_0001);
        @(posedge clk); #1;
        expect_reg(STATUS, 32'd1);
        expect_reg(CTRL, 32'd0);
        expect_irq(1'b0);

        // Reset in mid-run returns every register to zero.
        write(LOAD, 32'd5);
        write(CTRL, 32'h0000_0007);
        expect_irq(1'b1);
        rst_n = 1'b0;
        repeat (2) @(posedge clk);
        #1;
        rst_n = 1'b1;
        @(posedge clk); #1;
        expect_reg(CTRL, 32'd0);
        expect_reg(LOAD, 32'd0);
        expect_reg(COUNT, 32'd0);
        expect_reg(STATUS, 32'd0);
        expect_irq(1'b0);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
